function draw(source, canvas) {
  const ctx = canvas.getContext('2d')
  ctx.imageSmoothingEnabled = true
  ctx.imageSmoothingQuality = 'high'
  ctx.drawImage(source, 0, 0, canvas.width, canvas.height)
}

/**
 * @returns {Promise<'shared' | 'cancelled'>}
 */
export async function shareFiles(files) {
  try {
    await navigator.share({ files })
    return 'shared'
  } catch (err) {
    if (err && err.name === 'AbortError') return 'cancelled'
    throw err
  }
}

// 画像の上を指でなぞっても境目を動かせるようにする
const stage = $('compare-stage')
const move = (e) => {
  const rect = stage.getBoundingClientRect()
  setPosition(((e.clientX - rect.left) / rect.width) * 100)
}
stage.addEventListener('pointerdown', (e) => {
  stage.setPointerCapture(e.pointerId)
  move(e)
})
stage.addEventListener('pointermove', (e) => {
  if (stage.hasPointerCapture(e.pointerId)) move(e)
})

function tone(freq, { at = 0, dur = 0.12, type = 'sine', gain = 0.18, to = null } = {}) {
  const ac = audio()
  if (!ac) return
  const t = ac.currentTime + at
  const osc = ac.createOscillator()
  const amp = ac.createGain()
  osc.type = type
  osc.frequency.setValueAtTime(freq, t)
  if (to) osc.frequency.exponentialRampToValueAtTime(to, t + dur)
  amp.gain.setValueAtTime(0.0001, t)
  amp.gain.exponentialRampToValueAtTime(gain, t + 0.008)
  amp.gain.exponentialRampToValueAtTime(0.0001, t + dur)
  osc.connect(amp).connect(ac.destination)
  osc.start(t)
  osc.stop(t + dur + 0.02)

async function request() {
  if (sentinel || !('wakeLock' in navigator) || document.visibilityState !== 'visible') return
  try {
    sentinel = await navigator.wakeLock.request('screen')
    sentinel.addEventListener('release', () => {
      sentinel = null
    })
  } catch {
    sentinel = null
  }
}

/** 0 以上 n 未満の整数を偏りなく返す */
export function randInt(n) {
  if (!Number.isInteger(n) || n <= 0 || n > RANGE) {
    throw new RangeError(`randInt: n は 1〜2^32 の整数にしてください（${n}）`)
  }
  const limit = RANGE - (RANGE % n)
  let x
  do {
    x = nextUint32()
  } while (x >= limit)
  return x % n
}

